START_REGION_KEY = "S0:ROOT"
DEFAULT_LOCATION_REGION_KEY = "S0:ROOM:f9d207de6ebc30e499b8cbd565f41eeb"  # GatehouseSpawnRoom; 

def structurally_reachable_region_keys() -> frozenset[str]:
    """
    Return every authored region that can be reached from the AP
    starting region when all item requirements are ignored.

    This answers a different question from normal AP reachability:
    "Could this region EVER be reached through our modeled topology,
    assuming the player eventually owns every required item?"

    Regions absent from this set are structurally disconnected and
    therefore must not be trusted as progression-safe acquisition
    sources.
    """
    outgoing: dict[str, list[str]] = {}

    for edge in ENTRANCE_DATA:
        outgoing.setdefault(edge.source, []).append(
            edge.target
        )

    reachable: set[str] = {START_REGION_KEY}
    pending: list[str] = [START_REGION_KEY]

    while pending:
        source = pending.pop()

        for target in outgoing.get(source, ()):
            if target in reachable:
                continue

            reachable.add(target)
            pending.append(target)

    return frozenset(reachable)


def create_regions(world) -> dict[str, Region]:
    """Instantiate the first-pass Withering Rooms topology for one AP player."""
    menu = Region("Menu", world.player, world.multiworld)
    world.multiworld.regions.append(menu)

    created: dict[str, Region] = {}
    for key, data in REGION_DATA.items():
        region = Region(data.name, world.player, world.multiworld)
        created[key] = region
        world.multiworld.regions.append(region)

    menu.connect(created[START_REGION_KEY])

    for edge in ENTRANCE_DATA:
        source = created[edge.source]
        target = created[edge.target]
        rule = None

        required = edge.required_items

        # When Challenge Start is disabled, Gatehouse Key and
        # Strange Bedroom Key remain vanilla and therefore are
        # not AP progression requirements.
        if not world.options.challenge_start.value:
            required = tuple(
                item_name
                for item_name in required
                if item_name not in {
                    "Gatehouse Key",
                    "Strange Bedroom Key",
                }
            )

        if required:
            player = world.player
            rule = lambda state, required=required, player=player: all(
                state.has(item_name, player)
                for item_name in required
            )

        source.connect(target, rule=rule)

    return created
